import json, torch
E=W('model.language_model.embed_tokens.weight'); g=W('model.language_model.embedding_norm.weight')
U=E*g  # effective unembedding
cats=json.load(open('/work/cats.json'))
Un=U/U.norm(dim=1,keepdim=True)
res={}
for L in range(16):
    W2=W(f'model.language_model.layers.{L}.feed_forward.w2.weight')  # 1024x4608
    lg=Un@W2  # V x 4608
    mu=lg.mean(0); sd=lg.std(0)
    z={}
    for c,ids in cats.items():
        z[c]=((lg[ids].mean(0)-mu)/sd)
    res[L]={c:z[c] for c in z}
    line=[]
    for c in ['digit','code','cjk','cyr','latin_acc','mathop','ko','arab']:
        zz=z[c]; top=zz.abs().topk(64).values.mean().item()
        line.append(f"{c}:{top:.2f}")
    print(L,' '.join(line))
torch.save({L:{c:res[L][c] for c in res[L]} for L in res},'/work/catz.pt')

import torch, json
def fam(L,s,neg=None):
    w1=W(f'model.language_model.layers.{L}.feed_forward.w1.weight'); w2=W(f'model.language_model.layers.{L}.feed_forward.w2.weight')
    n1=w1/w1.norm(dim=1,keepdim=True); n2=(w2/w2.norm(dim=0,keepdim=True)).T
    sc=(n1@n1[s].T).abs().max(1).values+(n2@n2[s].T).abs().max(1).values
    if neg:
        sc=sc-((n1@n1[neg].T).abs().max(1).values+(n2@n2[neg].T).abs().max(1).values); sc[neg]=-10
    sc[s]=10; return sc
