import json, os, collections, torch
def hubs(L):
    cnt=collections.Counter()
    for f in os.listdir('/work'):
        if f.endswith('_64.json'):
            try: d=json.load(open('/work/'+f))
            except: continue
            if d.get('kind')=='mlp_cluster' and d['layer']==L:
                for i in d['indices']: cnt[i]+=1
    return [i for i,c in cnt.most_common(12) if c>=3]
def fam(L,s,neg):
    w1=W(f'model.language_model.layers.{L}.feed_forward.w1.weight'); w2=W(f'model.language_model.layers.{L}.feed_forward.w2.weight')
    n1=w1/w1.norm(dim=1,keepdim=True); n2=(w2/w2.norm(dim=0,keepdim=True)).T
    sc=(n1@n1[s].T).abs().max(1).values+(n2@n2[s].T).abs().max(1).values-((n1@n1[neg].T).abs().max(1).values+(n2@n2[neg].T).abs().max(1).values); sc[neg]=-10; sc[s]=10; return sc
for name,L,s,extra in [('week13h',13,[4519],[1649,2340,305,3830]),('past11h',11,[2157,2325,3967,4166,3840,4217],[3339,4506,2835,1484,2150]),('comp9h',9,[1790,4449,623,507,3298],[2150,1931,189,3406])]:
    neg=[x for x in hubs(L)+extra if x not in s]
    sc=fam(L,s,neg)
    json.dump({'kind':'mlp_cluster','layer':L,'indices':sorted(sc.topk(1024).indices.tolist())},open(f'/work/{name}_1024.json','w'))
